-- Domain 19: Cap Table & Valuation | functions
-- Generated by tools/split_by_domain.py. Statements keep their original order tag (@seq).

-- @seq 362
CREATE FUNCTION public.cap__equity_accounts(p_tenant_id uuid, p_entity_id uuid, p_class_type text) RETURNS TABLE(stock_account uuid, apic_account uuid, convertible_account uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  stock_account := CASE WHEN p_class_type = 'preferred'
    THEN acct__ensure_account(p_tenant_id, p_entity_id, '3310', 'Preferred Stock', 'equity', 'credit', 'equity', 'preferred_stock', 'preferred_stock', 'financing')
    ELSE acct__ensure_account(p_tenant_id, p_entity_id, '3300', 'Common Stock', 'equity', 'credit', 'equity', 'common_stock', 'common_stock', 'financing') END;
  apic_account := acct__ensure_account(p_tenant_id, p_entity_id, '3400', 'Additional Paid-in Capital', 'equity', 'credit', 'equity',
                                       'additional_paid_in_capital', 'additional_paid_in_capital', 'financing');
  convertible_account := acct__ensure_account(p_tenant_id, p_entity_id, '2750', 'SAFEs and Convertible Notes', 'liability', 'credit',
                                              'long_term_liability', 'convertible_securities', 'convertible_securities', 'financing');
  RETURN NEXT;
END $$;

-- @seq 363
CREATE FUNCTION public.cap__event(p_tenant_id uuid, p_type text, p_date date, p_stakeholder uuid, p_class uuid, p_shares numeric, p_amount numeric, p_related_type text, p_related_id uuid, p_details jsonb DEFAULT '{}'::jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  INSERT INTO cap_equity_events(tenant_id, event_type, event_date, stakeholder_id, share_class_id, shares, amount, related_type, related_id, details)
  VALUES (p_tenant_id, p_type, p_date, p_stakeholder, p_class, p_shares, p_amount, p_related_type, p_related_id, coalesce(p_details,'{}'::jsonb));
$$;

-- @seq 364
CREATE FUNCTION public.cap__months(p_from date, p_to date) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN p_to < p_from THEN -1 ELSE (extract(year FROM age(p_to, p_from)) * 12 + extract(month FROM age(p_to, p_from)))::int END;
$$;

-- @seq 365
CREATE FUNCTION public.cap_available_shares(p_class_id uuid) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT c.authorized_shares
         - coalesce((SELECT sum(i.shares) FROM cap_issuances i WHERE i.share_class_id = c.id AND i.status = 'active'), 0)
         - coalesce((SELECT sum(p.authorized_shares) FROM cap_option_pools p WHERE p.share_class_id = c.id), 0)
         + coalesce((SELECT sum(g.exercised_shares) FROM cap_option_grants g JOIN cap_option_pools p ON p.id = g.pool_id WHERE p.share_class_id = c.id), 0)
    FROM cap_share_classes c WHERE c.id = p_class_id;
$$;

-- @seq 366
CREATE FUNCTION public.cap_cancel_options(p_grant_id uuid, p_as_of date, p_reason text, p_unvested_only boolean DEFAULT true) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE g cap_option_grants%ROWTYPE; v numeric;
BEGIN
  SELECT * INTO g FROM cap_option_grants WHERE id = p_grant_id FOR UPDATE;
  IF NOT (platform_is_tenant_admin(g.tenant_id) OR auth.role() = 'service_role' OR platform_is_admin()) THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  v := CASE WHEN p_unvested_only THEN g.shares - g.cancelled_shares - greatest(cap_vested_shares(g.id, p_as_of), g.exercised_shares)
            ELSE g.shares - g.cancelled_shares - g.exercised_shares END;
  IF v <= 0 THEN RETURN 0; END IF;
  UPDATE cap_option_grants SET cancelled_shares = cancelled_shares + v,
         status = CASE WHEN exercised_shares + cancelled_shares + v >= shares THEN CASE WHEN exercised_shares > 0 THEN 'exercised' ELSE 'cancelled' END ELSE status END
   WHERE id = g.id;
  PERFORM cap__event(g.tenant_id, 'cancellation', p_as_of, g.stakeholder_id, NULL, v, NULL, 'cap_option_grants', g.id, jsonb_build_object('reason', p_reason));
  RETURN v;
END $$;

-- @seq 367
CREATE FUNCTION public.cap_close_round(p_round_id uuid, p_investments jsonb, p_close_date date, p_bank_account_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE r cap_funding_rounds%ROWTYPE; c cap_share_classes%ROWTYPE; v_total numeric; m jsonb; v_price numeric; x jsonb; v_iss uuid;
        cv cap_convertibles%ROWTYPE; a record; v_sh numeric; v_amt numeric; v_int numeric; v_par numeric; v_je uuid; v_pool uuid; v_lines jsonb;
BEGIN
  SELECT * INTO r FROM cap_funding_rounds WHERE id = p_round_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Round not found'; END IF;
  IF NOT (platform_is_tenant_admin(r.tenant_id) OR auth.role() = 'service_role' OR platform_is_admin()) THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  IF r.status IN ('closed','cancelled') THEN RAISE EXCEPTION 'Round is %', r.status; END IF;
  IF r.share_class_id IS NULL OR r.pre_money_valuation IS NULL THEN RAISE EXCEPTION 'Set the round share class and pre-money valuation first'; END IF;
  SELECT * INTO c FROM cap_share_classes WHERE id = r.share_class_id;
  SELECT coalesce(sum((e->>'amount')::numeric),0) INTO v_total FROM jsonb_array_elements(p_investments) e;
  IF v_total <= 0 THEN RAISE EXCEPTION 'Add the investors and amounts'; END IF;
  m := cap_model_round(r.tenant_id, r.pre_money_valuation, v_total, r.pool_target_pct, p_close_date, true);
  v_price := (m->>'price_per_share')::numeric;
  -- pool top-up first (it is part of the pre-money)
  IF (m->>'pool_increase')::numeric > 0 THEN
    v_pool := coalesce(r.option_pool_id, (SELECT id FROM cap_option_pools WHERE tenant_id = r.tenant_id ORDER BY created_at DESC LIMIT 1));
    IF v_pool IS NULL THEN RAISE EXCEPTION 'The model needs a pool increase but the company has no option pool'; END IF;
    IF cap_available_shares((SELECT share_class_id FROM cap_option_pools WHERE id = v_pool)) < (m->>'pool_increase')::numeric THEN
      RAISE EXCEPTION 'Not enough authorized common for the pool increase; amend the charter first';
    END IF;
    UPDATE cap_option_pools SET authorized_shares = authorized_shares + (m->>'pool_increase')::numeric WHERE id = v_pool;
    PERFORM cap__event(r.tenant_id, 'pool_increase', p_close_date, NULL, NULL, (m->>'pool_increase')::numeric, NULL, 'cap_option_pools', v_pool, '{}'::jsonb);
  END IF;
  UPDATE cap_share_classes SET original_issue_price = coalesce(original_issue_price, v_price) WHERE id = c.id;
  FOR x IN SELECT value FROM jsonb_array_elements(p_investments) LOOP
    v_sh := floor((x->>'amount')::numeric / v_price);
    v_iss := cap_issue_shares(r.tenant_id, (x->>'stakeholder_id')::uuid, c.id, v_sh, v_price, p_close_date, 'cash', p_bank_account_id,
                              NULL, r.id, r.board_consent_document_id, NULL, true, NULL, NULL, NULL, (x->>'amount')::numeric);
  END LOOP;
  SELECT * INTO a FROM cap__equity_accounts(r.tenant_id, c.entity_id, c.class_type);
  FOR x IN SELECT value FROM jsonb_array_elements(m->'conversions') LOOP
    SELECT * INTO cv FROM cap_convertibles WHERE id = (x->>'convertible_id')::uuid FOR UPDATE;
    v_sh := (x->>'shares')::numeric;
    v_int := CASE WHEN cv.instrument = 'convertible_note' THEN round(cv.principal * coalesce(cv.interest_rate,0) * (p_close_date - cv.issued_on) / 365.0, 2) ELSE 0 END;
    v_amt := cv.principal + v_int;
    v_iss := cap_issue_shares(r.tenant_id, cv.stakeholder_id, c.id, v_sh, round(v_amt / v_sh, 8), p_close_date, 'conversion', NULL, NULL, r.id,
                              r.board_consent_document_id, NULL, false, NULL, NULL, NULL, v_amt);
    v_par := least(round(v_sh * c.par_value, 2), v_amt);
    v_lines := jsonb_build_array(jsonb_build_object('account_id', a.convertible_account, 'debit', cv.principal, 'description', 'Conversion of ' || replace(cv.instrument,'_',' ')));
    IF v_int > 0 THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', acct__role(r.tenant_id, c.entity_id, 'interest_expense'), 'debit', v_int, 'description', 'Accrued note interest converted')); END IF;
    IF v_par > 0 THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', a.stock_account, 'credit', v_par)); END IF;
    IF v_amt > v_par THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', a.apic_account, 'credit', v_amt - v_par)); END IF;
    v_je := NULL;
    IF cv.journal_entry_id IS NOT NULL THEN   -- only convert on the books what was booked when the money came in
      v_je := acct_post_entry(r.tenant_id, c.entity_id, p_close_date, v_lines, 'equity_conversion', cv.id::text, NULL,
                              'Convert ' || replace(cv.instrument,'_',' ') || ' to ' || c.name, 'capconvx:' || cv.id, NULL, NULL, NULL, false, false, 'cap_convertibles', cv.id);
      UPDATE cap_issuances SET journal_entry_id = v_je WHERE id = v_iss;
    END IF;
    UPDATE cap_convertibles SET status = 'converted', converted_round_id = r.id, converted_issuance_id = v_iss, conversion_journal_id = v_je WHERE id = cv.id;
  END LOOP;
  UPDATE cap_funding_rounds SET status = 'closed', closed_on = p_close_date, price_per_share = v_price, model = m WHERE id = r.id;
  PERFORM cap__event(r.tenant_id, 'round_closed', p_close_date, NULL, c.id, (m->>'new_investor_shares')::numeric, v_total, 'cap_funding_rounds', r.id, m);
  RETURN m;
END $$;

-- @seq 368
CREATE FUNCTION public.cap_controls_check(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(severity text, check_code text, message text, related_type text, related_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $_$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  SELECT 'high', 'grant_below_fmv', 'Grant ' || g.grant_number || ' exercise price ' || g.exercise_price || ' is below FMV ' || v.fmv_per_common_share,
         'cap_option_grants', g.id
    FROM cap_option_grants g
    JOIN LATERAL (SELECT * FROM cap_valuations x WHERE x.tenant_id = g.tenant_id AND x.status = 'final' AND x.effective_date <= g.granted_on
                   ORDER BY x.effective_date DESC LIMIT 1) v ON true
   WHERE g.tenant_id = p_tenant_id AND g.grant_type <> 'rsu' AND g.exercise_price < v.fmv_per_common_share
  UNION ALL
  SELECT 'high', 'grant_without_current_409a', 'Grant ' || g.grant_number || ' on ' || g.granted_on || ' had no 409A valuation in effect',
         'cap_option_grants', g.id
    FROM cap_option_grants g
   WHERE g.tenant_id = p_tenant_id AND g.grant_type <> 'rsu'
     AND NOT EXISTS (SELECT 1 FROM cap_valuations x WHERE x.tenant_id = g.tenant_id AND x.status = 'final' AND x.valuation_type = '409a'
                       AND g.granted_on BETWEEN x.effective_date AND x.expires_on)
  UNION ALL
  SELECT 'medium', '409a_expiring', '409A from ' || x.effective_date || ' expires ' || x.expires_on, 'cap_valuations', x.id
    FROM cap_valuations x
   WHERE x.tenant_id = p_tenant_id AND x.status = 'final' AND x.valuation_type = '409a' AND x.expires_on < p_as_of + 60
     AND NOT EXISTS (SELECT 1 FROM cap_valuations y WHERE y.tenant_id = x.tenant_id AND y.status = 'final' AND y.valuation_type = '409a' AND y.effective_date > x.effective_date)
  UNION ALL
  SELECT 'medium', 'missing_board_consent', 'Issuance ' || i.certificate_no || ' has no board consent on file', 'cap_issuances', i.id
    FROM cap_issuances i WHERE i.tenant_id = p_tenant_id AND i.board_consent_document_id IS NULL AND i.consideration <> 'exercise'
  UNION ALL
  SELECT 'medium', 'missing_board_consent', 'Grant ' || g.grant_number || ' has no board consent on file', 'cap_option_grants', g.id
    FROM cap_option_grants g WHERE g.tenant_id = p_tenant_id AND g.board_consent_document_id IS NULL
  UNION ALL
  SELECT 'high', 'over_authorized', c.name || ' issued plus reserved exceeds authorized by ' || (-cap_available_shares(c.id)), 'cap_share_classes', c.id
    FROM cap_share_classes c WHERE c.tenant_id = p_tenant_id AND cap_available_shares(c.id) < 0
  UNION ALL
  SELECT 'high', 'pool_over_granted', p.name || ' has granted more than its reserve', 'cap_option_pools', p.id
    FROM cap_option_pools p WHERE p.tenant_id = p_tenant_id
     AND (SELECT coalesce(sum(g.shares - g.cancelled_shares),0) FROM cap_option_grants g WHERE g.pool_id = p.id) > p.authorized_shares
  UNION ALL
  SELECT 'medium', 'convertible_past_maturity', 'Note to ' || s.name || ' matured ' || cv.maturity_date || ' and is still outstanding', 'cap_convertibles', cv.id
    FROM cap_convertibles cv JOIN cap_stakeholders s ON s.id = cv.stakeholder_id
   WHERE cv.tenant_id = p_tenant_id AND cv.status = 'outstanding' AND cv.maturity_date < p_as_of
  UNION ALL
  SELECT 'low', 'not_on_books', 'Issuance ' || i.certificate_no || ' (' || i.consideration || ') has no journal entry', 'cap_issuances', i.id
    FROM cap_issuances i WHERE i.tenant_id = p_tenant_id AND i.journal_entry_id IS NULL AND i.amount > 0
  UNION ALL
  SELECT 'low', 'iso_100k_limit', s.name || ' has more than $100,000 of ISOs first exercisable in ' || y.yr || '; the excess is treated as NSO',
         'cap_stakeholders', s.id
    FROM (SELECT g.stakeholder_id sid, extract(year FROM (g.vesting_start + make_interval(months => g.cliff_months)))::int yr,
                 sum(g.shares * coalesce(v.fmv_per_common_share, g.exercise_price)) val
            FROM cap_option_grants g LEFT JOIN cap_valuations v ON v.id = g.valuation_id
           WHERE g.tenant_id = p_tenant_id AND g.grant_type = 'iso' AND g.vesting_months = 0 GROUP BY 1, 2) y
    JOIN cap_stakeholders s ON s.id = y.sid WHERE y.val > 100000
  UNION ALL
  SELECT 'low', 'stakeholder_not_linked', s.name || ' is not linked to a contact', 'cap_stakeholders', s.id
    FROM cap_stakeholders s WHERE s.tenant_id = p_tenant_id AND s.party_id IS NULL;
END $_$;

-- @seq 369
CREATE FUNCTION public.cap_events_immutable_trg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ BEGIN RAISE EXCEPTION 'Equity events are a permanent record; add a correcting event instead'; END $$;

-- @seq 370
CREATE FUNCTION public.cap_exercise_option(p_grant_id uuid, p_shares numeric, p_exercised_on date, p_bank_account_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE g cap_option_grants%ROWTYPE; p cap_option_pools%ROWTYPE; v_avail numeric; v_iss uuid; v_fmv numeric;
BEGIN
  SELECT * INTO g FROM cap_option_grants WHERE id = p_grant_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Grant not found'; END IF;
  SELECT * INTO p FROM cap_option_pools WHERE id = g.pool_id;
  IF NOT (platform_is_tenant_admin(g.tenant_id) OR auth.role() = 'service_role' OR platform_is_admin()) THEN
    RAISE EXCEPTION 'Only company owners and admins record exercises' USING ERRCODE = '42501';
  END IF;
  IF g.status <> 'active' THEN RAISE EXCEPTION 'Grant is %', g.status; END IF;
  IF g.grant_type = 'rsu' THEN RAISE EXCEPTION 'RSUs settle, they are not exercised'; END IF;
  IF g.expires_on IS NOT NULL AND p_exercised_on > g.expires_on THEN RAISE EXCEPTION 'Grant expired on %', g.expires_on; END IF;
  v_avail := CASE WHEN g.early_exercise THEN g.shares - g.cancelled_shares ELSE cap_vested_shares(g.id, p_exercised_on) END - g.exercised_shares;
  IF p_shares > v_avail THEN
    RAISE EXCEPTION 'Only % shares are vested and unexercised on % %', v_avail, p_exercised_on,
      CASE WHEN g.cliff_months > 0 AND p_exercised_on < (g.vesting_start + make_interval(months => g.cliff_months))::date
           THEN '(the vesting cliff ends ' || (g.vesting_start + make_interval(months => g.cliff_months))::date || ')' ELSE '' END;
  END IF;
  v_iss := cap_issue_shares(g.tenant_id, g.stakeholder_id, p.share_class_id, p_shares, g.exercise_price, p_exercised_on, 'exercise', p_bank_account_id);
  SELECT fmv_per_common_share INTO v_fmv FROM cap_valuations WHERE tenant_id = g.tenant_id AND status = 'final' AND effective_date <= p_exercised_on
   ORDER BY effective_date DESC LIMIT 1;
  INSERT INTO cap_option_exercises(tenant_id, grant_id, exercised_on, shares, price_paid, fmv_at_exercise, issuance_id)
  VALUES (g.tenant_id, g.id, p_exercised_on, p_shares, round(p_shares * g.exercise_price, 2), v_fmv, v_iss);
  UPDATE cap_option_grants SET exercised_shares = exercised_shares + p_shares,
         status = CASE WHEN exercised_shares + p_shares + cancelled_shares >= shares THEN 'exercised' ELSE status END
   WHERE id = g.id;
  RETURN v_iss;
END $$;

-- @seq 371
CREATE FUNCTION public.cap_grant_options(p_pool_id uuid, p_stakeholder_id uuid, p_shares numeric, p_exercise_price numeric, p_granted_on date, p_vesting_start date DEFAULT NULL::date, p_vesting_months integer DEFAULT 48, p_cliff_months integer DEFAULT 12, p_grant_type text DEFAULT 'iso'::text, p_board_consent_document_id uuid DEFAULT NULL::uuid, p_expires_on date DEFAULT NULL::date) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE p cap_option_pools%ROWTYPE; v_avail numeric; v_val cap_valuations%ROWTYPE; v uuid;
BEGIN
  SELECT * INTO p FROM cap_option_pools WHERE id = p_pool_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Option pool not found'; END IF;
  IF NOT (platform_is_tenant_admin(p.tenant_id) OR auth.role() = 'service_role' OR platform_is_admin()) THEN
    RAISE EXCEPTION 'Only company owners and admins can grant equity' USING ERRCODE = '42501';
  END IF;
  SELECT p.authorized_shares - coalesce(sum(g.shares - g.cancelled_shares),0) INTO v_avail FROM cap_option_grants g WHERE g.pool_id = p.id;
  IF v_avail < p_shares THEN RAISE EXCEPTION 'Only % shares left in %', v_avail, p.name; END IF;
  SELECT * INTO v_val FROM cap_valuations WHERE tenant_id = p.tenant_id AND status = 'final' AND effective_date <= p_granted_on
   ORDER BY effective_date DESC LIMIT 1;
  IF p_grant_type IN ('iso','nso','sar') AND v_val.id IS NOT NULL AND p_exercise_price < v_val.fmv_per_common_share THEN
    RAISE EXCEPTION 'Exercise price % is below the % fair market value % (IRC 409A); grant at or above FMV',
      p_exercise_price, to_char(v_val.effective_date,'YYYY-MM-DD'), v_val.fmv_per_common_share;
  END IF;
  INSERT INTO cap_option_grants(tenant_id, pool_id, stakeholder_id, grant_type, grant_number, granted_on, shares, exercise_price, vesting_start,
         vesting_months, cliff_months, expires_on, valuation_id, board_consent_document_id)
  VALUES (p.tenant_id, p.id, p_stakeholder_id, p_grant_type,
          'OG-' || lpad((SELECT count(*) + 1 FROM cap_option_grants WHERE tenant_id = p.tenant_id)::text, 4, '0'),
          p_granted_on, p_shares, p_exercise_price, coalesce(p_vesting_start, p_granted_on), p_vesting_months, p_cliff_months,
          coalesce(p_expires_on, (p_granted_on + interval '10 years')::date), v_val.id, p_board_consent_document_id)
  RETURNING id INTO v;
  PERFORM cap__event(p.tenant_id, 'grant', p_granted_on, p_stakeholder_id, p.share_class_id, p_shares, NULL, 'cap_option_grants', v,
                     jsonb_build_object('exercise_price', p_exercise_price, 'type', p_grant_type));
  RETURN v;
END $$;

-- @seq 372
CREATE FUNCTION public.cap_issue_shares(p_tenant_id uuid, p_stakeholder_id uuid, p_share_class_id uuid, p_shares numeric, p_price_per_share numeric, p_issue_date date, p_consideration text DEFAULT 'cash'::text, p_bank_account_id uuid DEFAULT NULL::uuid, p_offset_account_id uuid DEFAULT NULL::uuid, p_round_id uuid DEFAULT NULL::uuid, p_board_consent_document_id uuid DEFAULT NULL::uuid, p_certificate_no text DEFAULT NULL::text, p_post boolean DEFAULT true, p_vesting_start date DEFAULT NULL::date, p_vesting_months integer DEFAULT NULL::integer, p_cliff_months integer DEFAULT NULL::integer, p_amount numeric DEFAULT NULL::numeric) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE c cap_share_classes%ROWTYPE; a record; v_id uuid := gen_random_uuid(); v_amt numeric; v_par numeric; v_dr uuid; v_je uuid; v_lines jsonb;
BEGIN
  IF NOT (platform_is_tenant_admin(p_tenant_id) OR auth.role() = 'service_role' OR platform_is_admin()) THEN
    RAISE EXCEPTION 'Only company owners and admins can issue equity' USING ERRCODE = '42501';
  END IF;
  SELECT * INTO c FROM cap_share_classes WHERE id = p_share_class_id AND tenant_id = p_tenant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Share class not found'; END IF;
  IF NOT EXISTS (SELECT 1 FROM cap_stakeholders WHERE id = p_stakeholder_id AND tenant_id = p_tenant_id) THEN RAISE EXCEPTION 'Stakeholder not found'; END IF;
  IF coalesce(p_shares,0) <= 0 OR p_shares <> trunc(p_shares) THEN RAISE EXCEPTION 'Shares must be a positive whole number'; END IF;
  IF p_consideration <> 'exercise' AND cap_available_shares(c.id) < p_shares THEN
    RAISE EXCEPTION 'Only % % shares are available (authorized less issued and pool reserves); amend the charter first',
      cap_available_shares(c.id), c.name;
  END IF;
  -- p_amount = money actually received (a round prices whole shares, so the wire rarely equals shares x price;
  -- the difference belongs in paid-in capital, never a cash discrepancy)
  v_amt := coalesce(round(p_amount, 2), round(p_shares * coalesce(p_price_per_share,0), 2));
  IF p_amount IS NOT NULL AND abs(p_amount - p_shares * coalesce(p_price_per_share,0)) > greatest(coalesce(p_price_per_share,0), 0.01) THEN
    RAISE EXCEPTION 'Amount % does not match % shares at %', p_amount, p_shares, p_price_per_share;
  END IF;
  v_par := round(p_shares * c.par_value, 2);
  IF v_amt < v_par AND p_consideration IN ('cash','exercise') THEN
    RAISE EXCEPTION 'Price % is below par value % per share', p_price_per_share, c.par_value;
  END IF;
  SELECT * INTO a FROM cap__equity_accounts(p_tenant_id, c.entity_id, c.class_type);
  v_dr := CASE WHEN p_bank_account_id IS NOT NULL THEN acct_bank_gl(p_bank_account_id) ELSE p_offset_account_id END;
  IF p_post AND v_amt > 0 AND v_dr IS NOT NULL THEN
    v_lines := jsonb_build_array(jsonb_build_object('account_id', v_dr, 'debit', v_amt, 'description', p_shares || ' ' || c.name || ' shares'));
    IF v_par > 0 THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', a.stock_account, 'credit', least(v_par, v_amt), 'description', c.name || ' at par')); END IF;
    IF v_amt > v_par THEN v_lines := v_lines || jsonb_build_array(jsonb_build_object('account_id', a.apic_account, 'credit', v_amt - v_par, 'description', 'Paid-in capital over par')); END IF;
    v_je := acct_post_entry(p_tenant_id, c.entity_id, p_issue_date, v_lines, 'equity_issuance', v_id::text, p_certificate_no,
                            'Issue ' || p_shares || ' ' || c.name || ' shares', 'capiss:' || v_id, NULL, NULL, NULL, false, false, 'cap_issuances', v_id);
  END IF;
  INSERT INTO cap_issuances(id, tenant_id, stakeholder_id, share_class_id, round_id, certificate_no, shares, price_per_share, issue_date,
         consideration, amount, journal_entry_id, board_consent_document_id, vesting_start, vesting_months, cliff_months)
  VALUES (v_id, p_tenant_id, p_stakeholder_id, c.id, p_round_id,
          coalesce(p_certificate_no, CASE WHEN c.class_type = 'preferred' THEN 'PS-' ELSE 'CS-' END
                   || lpad((SELECT count(*) + 1 FROM cap_issuances WHERE tenant_id = p_tenant_id)::text, 4, '0')),
          p_shares, coalesce(p_price_per_share,0), p_issue_date, p_consideration, v_amt, v_je, p_board_consent_document_id,
          p_vesting_start, p_vesting_months, p_cliff_months);
  PERFORM cap__event(p_tenant_id, CASE WHEN p_consideration = 'exercise' THEN 'exercise' WHEN p_consideration = 'conversion' THEN 'conversion' ELSE 'issuance' END,
                     p_issue_date, p_stakeholder_id, c.id, p_shares, v_amt, 'cap_issuances', v_id, jsonb_build_object('price', p_price_per_share));
  RETURN v_id;
END $$;

-- @seq 373
CREATE FUNCTION public.cap_liquidation_waterfall(p_tenant_id uuid, p_exit_value numeric, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(share_class text, stakeholder_id uuid, holder_name text, shares numeric, preference numeric, participation numeric, total_payout numeric, per_share numeric, converted boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_iter int; v_rem numeric; v_tier record; v_tp numeric; v_pay numeric; v_ps numeric; v_den numeric; v_changed boolean;
        v_inner int; v_capped_any boolean; v_best uuid; v_part_pool numeric;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF coalesce(p_exit_value,0) < 0 THEN RAISE EXCEPTION 'Exit value cannot be negative'; END IF;
  DROP TABLE IF EXISTS pg_temp._cap_wf; DROP TABLE IF EXISTS pg_temp._cap_opt;
  CREATE TEMP TABLE _cap_wf ON COMMIT DROP AS
  SELECT c.id class_id, c.name, c.class_type ctype, c.seniority, sum(i.shares) shares, sum(i.shares) * c.conversion_ratio asconv,
         CASE WHEN c.class_type = 'preferred' THEN round(sum(i.shares * coalesce(nullif(i.price_per_share,0), c.original_issue_price, 0)) * c.liquidation_multiple, 2) ELSE 0 END pref,
         c.participating, CASE WHEN c.participating AND c.participation_cap_multiple IS NOT NULL
                               THEN round(sum(i.shares * coalesce(nullif(i.price_per_share,0), c.original_issue_price, 0)) * c.participation_cap_multiple, 2) END cap_total,
         (c.class_type = 'common') AS conv, false AS capped, 0::numeric pref_paid, 0::numeric part_paid
    FROM cap_share_classes c JOIN cap_issuances i ON i.share_class_id = c.id AND i.status = 'active' AND i.issue_date <= p_as_of
   WHERE c.tenant_id = p_tenant_id GROUP BY c.id;
  CREATE TEMP TABLE _cap_opt ON COMMIT DROP AS
  SELECT g.id grant_id, g.stakeholder_id sid,
         CASE WHEN g.acceleration = 'single_trigger' THEN g.shares - g.cancelled_shares ELSE cap_vested_shares(g.id, p_as_of) END - g.exercised_shares shares,
         g.exercise_price strike, true AS incl
    FROM cap_option_grants g WHERE g.tenant_id = p_tenant_id AND g.status = 'active' AND g.granted_on <= p_as_of AND g.grant_type <> 'rsu';
  DELETE FROM _cap_opt WHERE _cap_opt.shares <= 0;

  FOR v_iter IN 1..60 LOOP
    UPDATE _cap_wf SET pref_paid = 0, part_paid = 0, capped = false;
    v_rem := p_exit_value + coalesce((SELECT sum(o.shares * o.strike) FROM _cap_opt o WHERE o.incl), 0);
    FOR v_tier IN SELECT DISTINCT w.seniority FROM _cap_wf w WHERE w.ctype = 'preferred' AND NOT w.conv ORDER BY w.seniority DESC LOOP
      SELECT coalesce(sum(w.pref),0) INTO v_tp FROM _cap_wf w WHERE w.ctype = 'preferred' AND NOT w.conv AND w.seniority = v_tier.seniority;
      v_pay := least(v_rem, v_tp);
      IF v_tp > 0 THEN
        UPDATE _cap_wf w SET pref_paid = round(w.pref * v_pay / v_tp, 2) WHERE w.ctype = 'preferred' AND NOT w.conv AND w.seniority = v_tier.seniority;
      END IF;
      v_rem := v_rem - v_pay;
    END LOOP;
    -- participation with caps
    FOR v_inner IN 1..20 LOOP
      v_part_pool := v_rem - coalesce((SELECT sum(w.part_paid) FROM _cap_wf w WHERE w.capped), 0);
      SELECT coalesce(sum(w.asconv),0) INTO v_den FROM _cap_wf w WHERE (w.conv OR w.participating) AND NOT w.capped;
      v_den := v_den + coalesce((SELECT sum(o.shares) FROM _cap_opt o WHERE o.incl), 0);
      v_ps := CASE WHEN v_den > 0 THEN v_part_pool / v_den ELSE 0 END;
      v_capped_any := false;
      UPDATE _cap_wf w SET capped = true, part_paid = greatest(w.cap_total - w.pref_paid, 0)
       WHERE w.participating AND NOT w.conv AND NOT w.capped AND w.cap_total IS NOT NULL AND w.pref_paid + v_ps * w.asconv > w.cap_total
      RETURNING true INTO v_capped_any;
      EXIT WHEN NOT coalesce(v_capped_any, false);
    END LOOP;
    UPDATE _cap_wf w SET part_paid = round(v_ps * w.asconv, 2) WHERE (w.conv OR w.participating) AND NOT w.capped;
    v_changed := false;
    -- the preferred class that gains most by converting converts (one per pass)
    SELECT w.class_id INTO v_best FROM _cap_wf w
     WHERE w.ctype = 'preferred' AND NOT w.conv AND (NOT w.participating OR w.capped) AND v_ps * w.asconv > w.pref_paid + w.part_paid + 0.005
     ORDER BY v_ps * w.asconv - (w.pref_paid + w.part_paid) DESC LIMIT 1;
    IF v_best IS NOT NULL THEN UPDATE _cap_wf SET conv = true WHERE class_id = v_best; v_changed := true; v_best := NULL; END IF;
    UPDATE _cap_opt o SET incl = false WHERE o.incl AND o.strike >= v_ps;
    IF FOUND THEN v_changed := true; END IF;
    EXIT WHEN NOT v_changed;
  END LOOP;

  RETURN QUERY
  SELECT w.name::text, s.id, s.name::text, h.sh,
         round(CASE WHEN w.cbase > 0 THEN w.pref_paid * h.paid / w.cbase ELSE 0 END, 2), round(w.part_paid * h.sh / w.shares, 2),
         round(CASE WHEN w.cbase > 0 THEN w.pref_paid * h.paid / w.cbase ELSE 0 END + w.part_paid * h.sh / w.shares, 2),
         round((CASE WHEN w.cbase > 0 THEN w.pref_paid * h.paid / w.cbase ELSE 0 END + w.part_paid * h.sh / w.shares) / h.sh, 6),
         w.conv AND w.ctype = 'preferred'
    FROM (SELECT x.*, (SELECT sum(i.shares * coalesce(nullif(i.price_per_share,0), cc.original_issue_price, 0))
                         FROM cap_issuances i JOIN cap_share_classes cc ON cc.id = i.share_class_id
                        WHERE i.share_class_id = x.class_id AND i.status = 'active' AND i.issue_date <= p_as_of) cbase
            FROM _cap_wf x) w
    JOIN (SELECT i.share_class_id cid, i.stakeholder_id sid, sum(i.shares) sh,
                 sum(i.shares * coalesce(nullif(i.price_per_share,0), cc.original_issue_price, 0)) paid
            FROM cap_issuances i JOIN cap_share_classes cc ON cc.id = i.share_class_id
           WHERE i.tenant_id = p_tenant_id AND i.status = 'active' AND i.issue_date <= p_as_of GROUP BY 1, 2) h ON h.cid = w.class_id
    JOIN cap_stakeholders s ON s.id = h.sid
  UNION ALL
  SELECT 'Options (as exercised)', s.id, s.name::text, sum(o.shares), 0::numeric, round(sum(o.shares * (v_ps - o.strike)), 2),
         round(sum(o.shares * (v_ps - o.strike)), 2), round(v_ps, 6), false
    FROM _cap_opt o JOIN cap_stakeholders s ON s.id = o.sid WHERE o.incl GROUP BY s.id, s.name
  ORDER BY 7 DESC;
END $$;

-- @seq 374
CREATE FUNCTION public.cap_model_round(p_tenant_id uuid, p_pre_money numeric, p_investment numeric, p_pool_target_pct numeric DEFAULT NULL::numeric, p_as_of date DEFAULT CURRENT_DATE, p_include_convertibles boolean DEFAULT true) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v_fd numeric; v_pool numeric; v_price numeric; v_delta numeric := 0; v_conv numeric := 0; v_new numeric; v_total numeric;
        i int; c record; v_cap_price numeric; v_disc_price numeric; v_cp numeric; v_amt numeric; v_prev numeric; v_convs jsonb;
        v_holders jsonb; v_last numeric := 0;
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  IF coalesce(p_pre_money,0) <= 0 OR coalesce(p_investment,0) < 0 THEN RAISE EXCEPTION 'Pre-money valuation must be positive and investment non-negative'; END IF;
  IF p_pool_target_pct IS NOT NULL AND (p_pool_target_pct < 0 OR p_pool_target_pct >= 1) THEN RAISE EXCEPTION 'Pool target is a fraction between 0 and 1'; END IF;
  SELECT coalesce(sum(fully_diluted),0), coalesce(sum(fully_diluted) FILTER (WHERE holder_kind = 'unallocated_pool'),0)
    INTO v_fd, v_pool FROM cap_table(p_tenant_id, p_as_of);
  IF v_fd <= 0 THEN RAISE EXCEPTION 'No shares outstanding yet; issue founder shares first'; END IF;
  FOR i IN 1..200 LOOP
    v_prev := coalesce(v_price, 0);
    v_price := p_pre_money / (v_fd + v_delta + v_conv);
    v_last := v_conv;
    v_conv := 0;
    IF p_include_convertibles THEN
      FOR c IN SELECT * FROM cap_convertibles WHERE tenant_id = p_tenant_id AND status = 'outstanding' AND issued_on <= p_as_of LOOP
        v_amt := c.principal + CASE WHEN c.instrument = 'convertible_note'
                                    THEN round(c.principal * coalesce(c.interest_rate,0) * (p_as_of - c.issued_on) / 365.0, 2) ELSE 0 END;
        v_cap_price := CASE WHEN c.valuation_cap IS NULL THEN NULL
                            WHEN c.instrument = 'safe_post_money' THEN c.valuation_cap / (v_fd + v_last)
                            ELSE c.valuation_cap / v_fd END;
        v_disc_price := CASE WHEN c.discount_rate IS NULL THEN NULL ELSE v_price * (1 - c.discount_rate) END;
        v_cp := least(coalesce(v_cap_price, v_price), coalesce(v_disc_price, v_price), v_price);
        v_conv := v_conv + floor(v_amt / v_cp);
      END LOOP;
    END IF;
    v_new := floor(p_investment / v_price);
    v_total := v_fd + v_delta + v_conv + v_new;
    IF p_pool_target_pct IS NOT NULL THEN v_delta := greatest(0, ceil(p_pool_target_pct * v_total - v_pool)); END IF;
    EXIT WHEN abs(v_price - v_prev) < 0.0000001;
  END LOOP;
  v_price := p_pre_money / (v_fd + v_delta + v_conv);
  v_new := floor(p_investment / v_price);
  v_total := v_fd + v_delta + v_conv + v_new;
  SELECT coalesce(jsonb_agg(jsonb_build_object('convertible_id', cc.id, 'holder', s.name, 'instrument', cc.instrument, 'amount', cc.principal,
            'shares', floor((cc.principal + CASE WHEN cc.instrument = 'convertible_note' THEN round(cc.principal * coalesce(cc.interest_rate,0) * (p_as_of - cc.issued_on) / 365.0, 2) ELSE 0 END)
                      / least(coalesce(CASE WHEN cc.valuation_cap IS NULL THEN NULL WHEN cc.instrument = 'safe_post_money' THEN cc.valuation_cap / (v_fd + v_conv) ELSE cc.valuation_cap / v_fd END, v_price),
                              coalesce(v_price * (1 - cc.discount_rate), v_price), v_price)))), '[]'::jsonb)
    INTO v_convs FROM cap_convertibles cc JOIN cap_stakeholders s ON s.id = cc.stakeholder_id
   WHERE p_include_convertibles AND cc.tenant_id = p_tenant_id AND cc.status = 'outstanding' AND cc.issued_on <= p_as_of;
  SELECT jsonb_agg(jsonb_build_object('holder', holder_name, 'kind', holder_kind, 'shares', fd,
           'pct_before', round(fd / v_fd * 100, 4), 'pct_after', round(fd / v_total * 100, 4)) ORDER BY fd DESC)
    INTO v_holders FROM (SELECT holder_name, holder_kind, sum(fully_diluted) fd FROM cap_table(p_tenant_id, p_as_of) GROUP BY 1, 2) h;
  RETURN jsonb_build_object(
    'pre_money', p_pre_money, 'investment', p_investment, 'price_per_share', round(v_price, 6),
    'fully_diluted_before', v_fd, 'pool_increase', v_delta, 'conversion_shares', v_conv, 'new_investor_shares', v_new,
    'fully_diluted_after', v_total, 'post_money', round(v_price * v_total, 2),
    'new_investor_pct', round(v_new / v_total * 100, 4), 'pool_pct_after', round((v_pool + v_delta) / v_total * 100, 4),
    'conversions', v_convs, 'existing_holders', coalesce(v_holders, '[]'::jsonb));
END $$;

-- @seq 375
CREATE FUNCTION public.cap_record_convertible(p_tenant_id uuid, p_stakeholder_id uuid, p_instrument text, p_principal numeric, p_issued_on date, p_valuation_cap numeric DEFAULT NULL::numeric, p_discount_rate numeric DEFAULT NULL::numeric, p_interest_rate numeric DEFAULT NULL::numeric, p_maturity_date date DEFAULT NULL::date, p_bank_account_id uuid DEFAULT NULL::uuid, p_mfn boolean DEFAULT false, p_document_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
DECLARE v uuid := gen_random_uuid(); v_e uuid := acct_default_entity(p_tenant_id); a record; v_je uuid;
BEGIN
  IF NOT (platform_is_tenant_admin(p_tenant_id) OR auth.role() = 'service_role' OR platform_is_admin()) THEN RAISE EXCEPTION 'Not allowed' USING ERRCODE = '42501'; END IF;
  IF p_valuation_cap IS NULL AND p_discount_rate IS NULL AND NOT p_mfn THEN RAISE EXCEPTION 'A SAFE or note needs a valuation cap, a discount, or MFN'; END IF;
  IF p_bank_account_id IS NOT NULL THEN
    SELECT * INTO a FROM cap__equity_accounts(p_tenant_id, v_e, 'common');
    v_je := acct_post_entry(p_tenant_id, v_e, p_issued_on, jsonb_build_array(
              jsonb_build_object('account_id', acct_bank_gl(p_bank_account_id), 'debit', p_principal, 'description', replace(p_instrument,'_',' ')),
              jsonb_build_object('account_id', a.convertible_account, 'credit', p_principal, 'description', replace(p_instrument,'_',' '))),
            'equity_convertible', v::text, NULL, 'Convertible ' || replace(p_instrument,'_',' '), 'capconv:' || v, NULL, NULL, NULL, false, false, 'cap_convertibles', v);
  END IF;
  INSERT INTO cap_convertibles(id, tenant_id, stakeholder_id, instrument, principal, issued_on, valuation_cap, discount_rate, interest_rate,
         maturity_date, mfn, journal_entry_id, document_id)
  VALUES (v, p_tenant_id, p_stakeholder_id, p_instrument, p_principal, p_issued_on, p_valuation_cap, p_discount_rate, p_interest_rate,
          p_maturity_date, p_mfn, v_je, p_document_id);
  RETURN v;
END $$;

-- @seq 376
CREATE FUNCTION public.cap_table(p_tenant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS TABLE(holder_kind text, stakeholder_id uuid, holder_name text, share_class text, issued_shares numeric, options_outstanding numeric, options_vested numeric, fully_diluted numeric, pct_outstanding numeric, pct_fully_diluted numeric)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
BEGIN
  PERFORM acct_assert_access(p_tenant_id);
  RETURN QUERY
  WITH iss AS (
    SELECT i.stakeholder_id sid, i.share_class_id cid, sum(i.shares) sh FROM cap_issuances i
     WHERE i.tenant_id = p_tenant_id AND i.status = 'active' AND i.issue_date <= p_as_of GROUP BY 1, 2),
  opt AS (
    SELECT g.stakeholder_id sid, p.share_class_id cid, sum(g.shares - g.exercised_shares - g.cancelled_shares) sh,
           sum(greatest(cap_vested_shares(g.id, p_as_of) - g.exercised_shares, 0)) vested
      FROM cap_option_grants g JOIN cap_option_pools p ON p.id = g.pool_id
     WHERE g.tenant_id = p_tenant_id AND g.granted_on <= p_as_of AND g.status = 'active' GROUP BY 1, 2),
  pool AS (
    SELECT p.id, p.name, p.share_class_id cid,
           p.authorized_shares - coalesce((SELECT sum(g.shares - g.cancelled_shares) FROM cap_option_grants g
                                             WHERE g.pool_id = p.id AND g.granted_on <= p_as_of), 0) unalloc
      FROM cap_option_pools p WHERE p.tenant_id = p_tenant_id AND coalesce(p.adopted_on, p_as_of) <= p_as_of),
  rows_ AS (
    SELECT 'stakeholder'::text k, coalesce(i.sid, o.sid) sid, coalesce(i.cid, o.cid) cid, coalesce(i.sh,0) iss, coalesce(o.sh,0) opt, coalesce(o.vested,0) ves
      FROM iss i FULL JOIN opt o ON o.sid = i.sid AND o.cid = i.cid
    UNION ALL
    SELECT 'unallocated_pool', NULL, pl.cid, 0, pl.unalloc, 0 FROM pool pl WHERE pl.unalloc > 0),
  tot AS (SELECT sum(iss) t_out, sum(iss + opt) t_fd FROM rows_)
  SELECT r.k, r.sid, coalesce(s.name, 'Unallocated option pool')::text, c.name::text, r.iss, r.opt, r.ves, r.iss + r.opt,
         round(r.iss / nullif(t.t_out,0) * 100, 4), round((r.iss + r.opt) / nullif(t.t_fd,0) * 100, 4)
    FROM rows_ r CROSS JOIN tot t LEFT JOIN cap_stakeholders s ON s.id = r.sid JOIN cap_share_classes c ON c.id = r.cid
   ORDER BY r.k DESC, (r.iss + r.opt) DESC;
END $$;

-- @seq 377
CREATE FUNCTION public.cap_vested_shares(p_grant_id uuid, p_as_of date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT CASE
           WHEN g.id IS NULL THEN 0
           WHEN cap__months(g.vesting_start, p_as_of) < 0 THEN 0
           WHEN g.vesting_months = 0 THEN g.shares - g.cancelled_shares
           WHEN cap__months(g.vesting_start, p_as_of) < g.cliff_months THEN 0
           ELSE least(g.shares - g.cancelled_shares,
                      floor(g.shares * least(g.vesting_months,
                            (cap__months(g.vesting_start, p_as_of) / g.vesting_frequency_months) * g.vesting_frequency_months)::numeric
                            / g.vesting_months))
         END
    FROM cap_option_grants g WHERE g.id = p_grant_id;
$$;

